import{_ as r,l as s,o as t,c as n,v as e,p as h,x as i,d as l,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"OLS 与稳健标准误","description":"","frontmatter":{"title":"OLS 与稳健标准误","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ols-robust-se.md","filePath":"quant/ols-robust-se.md","lastUpdated":1789023840000}'),d={name:"quant/ols-robust-se.md"};function B(c,a,u,m,_,A){const o=s("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="ols-与稳健标准误" tabindex="-1">OLS 与稳健标准误 <a class="header-anchor" href="#ols-与稳健标准误" aria-label="Permalink to &quot;OLS 与稳健标准误&quot;">​</a></h1><div class="epigraph"><p>普通最小二乘的点估计在外生与满秩下仍然可用；一旦残差方差随观测而变，沿用同方差公式算出的 t 值，只是把异方差当成了额外的样本量。</p><footer>—— White, A Heteroskedasticity-Consistent Covariance Matrix Estimator and a Direct Test for Heteroskedasticity, Econometrica, 1980</footer></div><p>上一课 <a href="/quant/fx-last-look">FX last look</a> 把外汇报价权写成可拒绝的期权：成交是否发生、价差是否被选走，都是事后才观测到的金融结果。从本课起，对象从市场设计转到<strong>在这些结果上做推断</strong>。斜率仍用 OLS 去估——White 没有改点估计——但金融残差几乎从不同方差：大市值日、危机日、薄股票日的 \\(\\varepsilon^2\\) 差一个数量级。同方差 \\(t\\) 会把「某几天特别吵」读成「系数特别准」。本课只处理截面或可当作独立的异方差；序列相关留给 <a href="/quant/newey-west">Newey–West</a>，面板聚类留给下一课之后。后课默认：你已经会在金融回归里报 White 稳健标准误，而不是把软件默认的 OLS 标准误当结论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性模型 \\(y_i=x_i^\\top\\beta+u_i\\)。外生 \\(E[u_i\\mid x_i]=0\\)、设计满秩时，\\(\\hat\\beta=(X^\\top X)^{-1}X^\\top y\\) 仍一致。同方差公式</p> \\[\\widehat{\\mathrm{Var}}(\\hat\\beta)=\\hat\\sigma^2(X^\\top X)^{-1} \\]<p>要求 \\(E[u_i^2\\mid x_i]=\\sigma^2\\)。金融里这一条先坏：波动聚集、规模异质、事件日方差跳升，都会让 \\(u_i^2\\) 跟着 \\(x_i\\) 或日历走。问题不是「要不要回归」，而是 <strong>\\(t\\) 的分母该不该假装每个观测贡献同样的信息</strong>。</p><p>White 的对象是条件异方差下 \\(\\hat\\beta\\) 的渐近方差，不是改 \\(\\hat\\beta\\) 本身。把稳健标准误理解成「换了一种估计量」，会和后课的 GMM、分位回归抢对象。</p><h3 id="金融回归的残差不是实验残差" tabindex="-1">金融回归的残差不是实验残差 <a class="header-anchor" href="#金融回归的残差不是实验残差" aria-label="Permalink to &quot;金融回归的残差不是实验残差&quot;">​</a></h3><p>随机分配的实验里，处理指示与误差方差大致可分。收益对因子、价差对 tick、拒绝率对库存，左边的尺度随市况变，右边的变量往往与尺度相关。大股票的 \\(\\beta\\) 估得更准，不是因为模型更好，是因为 \\(u_i\\) 更小。把全部股票等权塞进一次 OLS，点估计被薄股票拉，标准误若再假设同方差，薄股票的噪声会被当成「很多独立证据」。</p><p><span class="marginnote">稳健标准误修正的是方差估计，不修正遗漏变量与反向因果。last look 是否「降低毒性」若用事后拒绝当处理、用同期收益当结果，识别问题仍在；White 只保证你不会用错的精度去宣布一个有偏斜率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>三明治。</strong> White 用</p> \\[\\widehat{\\mathrm{Var}}(\\hat\\beta)=(X^\\top X)^{-1}\\Bigl(\\sum_i x_i x_i^\\top\\hat u_i^2\\Bigr)(X^\\top X)^{-1}. \\]<p>中间是得分的经验二阶矩。异方差时它一致；同方差时多估了一些，效率略差，通常可忽略。有限样本里 \\(\\hat u_i\\) 偏小，MacKinnon–White 的 HC1/HC2/HC3 对杠杆点再加权，金融截面（几只极端收益）应默认 HC3 一类，而不是教科书 HC0。</p><p><strong>诊断仍要做。</strong> 稳健标准误不是许可证：先看残差对拟合值、对规模、对波动代理的散点。若方差结构已知（如按成交额加权），加权最小二乘更有效，White 是不知道结构时的保守默认。Breusch–Pagan 在金融里很容易拒绝，拒绝后仍用 OLS+White，而不是改成必须同方差才合法。</p><p><strong>与 <a href="/quant/arma">ARMA</a> / <a href="/quant/garch">GARCH</a> 的分工。</strong> 均值方程用 OLS 抽线性关系；若对象是条件方差，应换 GARCH，而不是把平方残差的结构硬塞进 White 再宣布「已经稳健」。White 吃掉的是方差公式的误设，不是均值的动态误设。</p><h3 id="何时同方差公式就够" tabindex="-1">何时同方差公式就够 <a class="header-anchor" href="#何时同方差公式就够" aria-label="Permalink to &quot;何时同方差公式就够&quot;">​</a></h3><p>日度指数超额对少数宏观意外、样本已按波动标准化、杠杆点已修剪时，两种标准误会接近。接近不是证明同方差，只说明异方差没在这个设计里主导精度。报告应并列两者：若结论只在同方差下成立，结论不成立。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OLS 把每个 \\(x_i u_i\\) 加总。同方差时，信息量由 \\(X^\\top X\\) 决定。异方差时，大 \\(u_i^2\\) 的观测把总分的波动抬高，却不一定把 \\(X^\\top X\\) 抬同样多——尤其当高方差观测的 \\(x\\) 并不更大。三明治的中间项正是在数「得分有多抖」。杠杆点（\\(x\\) 远离中心）若同时是高方差日，会同时污染点估计与精度；HC3 把这些点的 \\(\\hat u_i^2\\) 放大，等于承认它们不该被当成普通观测。</p><p>机制上这是 M 估计的标准论：估计方程无偏，方差用得分的外积。金融面板稍后会把「独立观测」这条再拆掉；本课先把<strong>截面异方差</strong>从同方差公式里分离出来。</p><p><span class="marginnote">\\(R^2\\) 与 White 无关。高 \\(R^2\\) 的因子回归，α 的 t 仍可能被同期残差相关夸大——那是 <a href="/quant/fama-macbeth">Fama–MacBeth</a> 与聚类要管的事，不是本课的三明治能代替的。</span></p><h3 id="加权、变换与对象" tabindex="-1">加权、变换与对象 <a class="header-anchor" href="#加权、变换与对象" aria-label="Permalink to &quot;加权、变换与对象&quot;">​</a></h3><p>对 \\(|y|\\) 很大的观测做 winsorize，是改点估计；用 White，是改标准误。两者都常用，对象不同。对数收益已经是一种稳定方差的变换，但危机日仍更吵。把收益除以滞后已实现波动再回归，接近加权，此时 White 与同方差会靠近——这是你把异方差模型化了，不是稳健标准误「失效」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>White 要求观测在时间或个体上足够接近独立。日收益回归里残差有 <a href="/quant/garch">GARCH</a> 式聚集，三明治会偏小，必须接到 Newey–West。个股月收益对特征的截面，同期相关是主问题，应接到聚类或 Fama–MacBeth，而不是只开 <code>cov_type=&#39;HC3&#39;</code>。极少数观测、极高维 \\(x\\)，中间矩阵噪声大，稳健标准误会不稳定——应减参数或用 bootstrap。</p><p>工程上：默认对所有金融 OLS 开异方差稳健；把同方差作为对照列。不要用稳健 t 去补识别。不要在重叠长期收益上只用 White（见后课重叠观测）。不要把 White 的「通过」写成「残差已独立同分布」。</p><p><span class="marginnote">软件里 <code>robust</code> 一词混用 White、HAC、聚类。报告须写清是 HC 哪一档、有没有滞后、有没有按实体聚类。复现失败常常是这一行没写。</span></p>',29)),(t(),h(p,null,{default:i(()=>[E(o,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E9%87%91%E8%9E%8D%E7%BB%93%E6%9E%9C%20y%22%5D%20--%3E%20OLS%5B%22OLS%20%E7%82%B9%E4%BC%B0%E8%AE%A1%20%CE%B2%22%5D%0A%20%20X%5B%22%E5%9B%9E%E5%BD%92%E5%85%83%20x%22%5D%20--%3E%20OLS%0A%20%20OLS%20--%3E%20U%5B%22%E6%AE%8B%E5%B7%AE%20u%22%5D%0A%20%20U%20--%3E%20HOM%7B%22%E5%90%8C%E6%96%B9%E5%B7%AE%E5%85%AC%E5%BC%8F%3F%22%7D%0A%20%20HOM%20--%3E%7C%E5%90%A6%2C%20%E6%88%AA%E9%9D%A2%E5%BC%82%E6%96%B9%E5%B7%AE%7C%20W%5B%22White%20%E4%B8%89%E6%98%8E%E6%B2%BB%22%5D%0A%20%20HOM%20--%3E%7C%E6%AE%8B%E5%B7%AE%E8%BF%98%E5%BA%8F%E5%88%97%E7%9B%B8%E5%85%B3%7C%20NW%5B%22%E4%BA%A4%E7%BB%99%20Newey-West%22%5D%0A%20%20HOM%20--%3E%7C%E9%9D%A2%E6%9D%BF%E5%90%8C%E6%9C%9F%E7%9B%B8%E5%85%B3%7C%20CL%5B%22%E4%BA%A4%E7%BB%99%E8%81%9A%E7%B1%BB%20%2F%20FM%22%5D%0A%20%20W%20--%3E%20T%5B%22t%20%E4%B8%8E%E7%BD%AE%E4%BF%A1%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>金融 OLS 的斜率在外生下仍可用；坏的是同方差标准误，不是最小二乘本身。</li><li>White 用得分外积估计 \\(\\mathrm{Var}(\\hat\\beta)\\)，HC3 一类对杠杆更稳，应作为截面默认。</li><li>它不处理序列相关、聚类、重叠观测，也不修复内生。</li><li>与加权、变换、GARCH 的分工：能模型化方差则更有效；不能则用三明治保守报精度。</li><li>出处：White, <em>Econometrica</em>, 1980；有限样本形式见 MacKinnon and White, <em>Journal of Econometrics</em>, 1985。</li></ul>',2))])}const f=r(d,[["render",B]]);export{b as __pageData,f as default};
